// Generated by Webura so routing works inside the preview and share links.
// Webura only writes this file when it is missing; edits to it are kept.
const PREVIEW_BASE_RE = /^(\/api\/v1\/preview\/\d+|\/s\/[A-Za-z0-9]+)(?:\/|$)/;

export function getPreviewRouterBasename(
  pathname: string = window.location.pathname,
): string | undefined {
  const match = pathname.match(PREVIEW_BASE_RE);
  return match?.[1];
}
